run compute network-firewall-policies rules create 1180 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=line 46'
run compute network-firewall-policies rules create 1190 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=line 46'
run compute network-firewall-policies rules create 1200 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all '--description=line 46'
run compute network-firewall-policies rules create 1210 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all '--description=line 46'
run compute network-firewall-policies rules create 1220 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-allow
